abstract class BaseScreen {
    private val log = mutableListOf<String>()
    fun start(): String {
        log += "setup"
        log += render()
        onStarted(log)
        return log.joinToString(" > ")
    }
    protected abstract fun render(): String
    protected open fun onStarted(log: MutableList<String>) { log += "done" }
}
class Home : BaseScreen() { override fun render() = "home" }
class Profile : BaseScreen() {
    override fun render() = "profile"
    override fun onStarted(log: MutableList<String>) {}
}

fun main() {
    println(Home().start())
    println(Profile().start())
}

